            harga    = self.lineEdit_6.text()

            sql = "UPDATE product SET name = %s, barkode = %s, kategori = %s, qty = %s, harga = %s WHERE id = %s"
            val = (name, barkode, kategori, qty, harga, id)
            cursor.execute(sql, val)
            mydb.commit()
            self.label_7.setText("Data Product Berhasil DiUpdate")
            
            self.lineEdit_3.setText("")
            self.lineEdit.setText("")
            self.lineEdit_2.setText("")
