    def deleteproduct(self):
        try:
            mydb = mc.connect(
                host="localhost",
                user="root",
                password="",
                port="3306",
                database="db_penjualan2"
            )

            cursor = mydb.cursor()
            idkat = self.lineEdit.text()
            
            if not idkat:  # Memeriksa apakah ID kategori kosong
                self.label_7.setText("Masukkan ID Product yang ingin Dihapus")
                return

            sql = "DELETE FROM product where id = %s"
            val = (idkat,)
            cursor.execute(sql, val)
            mydb.commit()

            self.label_7.setText("Data Product Berhasil Dihapus")

            self.lineEdit.setText("")
        except mc.Error as e:
            print(sql)
            self.label_7.setText("Data Product Gagal DiHapus")
            
            
    def searchproduct(self):
        try:
            mydb = mc.connect(
                host="localhost",
                user="root",
                password="",
                port="3306",
                database="db_penjualan2"
            )

            mycursor = mydb.cursor()
            namekat = self.lineEdit_7.text()
            
            if not namekat:
                self.label_7.setText("Masukkan ID Product yang ingin di Cari")
                return
        
            sql = "SELECT * FROM product WHERE id LIKE %s"
            mycursor.execute(sql, (namekat + '%',))
            result = mycursor.fetchall()
            self.tableWidget.setRowCount(0)
            for row_number, row_data in enumerate(result):
                self.tableWidget.insertRow(row_number)
                for column_number, data in enumerate(row_data):
                    self.tableWidget.setItem(row_number, column_number, QTableWidgetItem(str(data)))
            self.label_7.setText("Data Product Berhasil Ditampilkan")

        except mc.Error as err:
            self.label_7.setText("Data Product Gagal DiLoad")


    def loadproduct(self):
        try:
            mydb = mc.connect(
                host="localhost",
                user="root",
                password="",
                port="3306",
                database="db_penjualan2"
            )

            mycursor = mydb.cursor()
            mycursor.execute("SELECT * FROM product ORDER BY ID ASC")
            result = mycursor.fetchall()
            self.tableWidget.setRowCount(0)
            for row_number, row_data in enumerate(result):
                self.tableWidget.insertRow(row_number)
                for column_number, data in enumerate(row_data):
                    self.tableWidget.setItem(row_number, column_number, QTableWidgetItem(str(data)))
            self.label_7.setText("Data Product Berhasil Ditampilkan")

        except mc.Error as err:
            self.label_7.setText("Data Product Gagal DiLoad")

